import sys

def main():
    data = sys.stdin.read().split()
    q = int(data[0])
    p = 1
    key, L, R = [], [], []
    root = -1
    out = []
    for _ in range(q):
        op = data[p]
        p += 1
        if op == 'INSERT':
            x = int(data[p])
            p += 1
            if root == -1:
                key.append(x); L.append(-1); R.append(-1)
                root = 0
                out.append('1')
                continue
            cur = root
            while True:
                if x == key[cur]:
                    out.append('0')
                    break
                go_left = x < key[cur]
                nxt = L[cur] if go_left else R[cur]
                if nxt == -1:
                    idx = len(key)
                    key.append(x); L.append(-1); R.append(-1)
                    if go_left:
                        L[cur] = idx
                    else:
                        R[cur] = idx
                    out.append('1')
                    break
                cur = nxt
        elif op == 'SEARCH':
            x = int(data[p])
            p += 1
            cur = root
            while cur != -1 and key[cur] != x:
                cur = L[cur] if x < key[cur] else R[cur]
            out.append('1' if cur != -1 else '0')
        elif op == 'DELETE':
            x = int(data[p])
            p += 1
            par, cur = -1, root
            while cur != -1 and key[cur] != x:
                par = cur
                cur = L[cur] if x < key[cur] else R[cur]
            if cur == -1:
                out.append('0')
                continue
            if L[cur] != -1 and R[cur] != -1:
                sp, s = cur, R[cur]
                while L[s] != -1:
                    sp, s = s, L[s]
                key[cur] = key[s]
                if sp == cur:
                    R[sp] = R[s]
                else:
                    L[sp] = R[s]
            else:
                child = L[cur] if L[cur] != -1 else R[cur]
                if par == -1:
                    root = child
                elif L[par] == cur:
                    L[par] = child
                else:
                    R[par] = child
            out.append('1')
        elif op == 'MIN' or op == 'MAX':
            if root == -1:
                out.append('EMPTY')
            else:
                cur = root
                nxt = L if op == 'MIN' else R
                while nxt[cur] != -1:
                    cur = nxt[cur]
                out.append(str(key[cur]))
        elif op == 'HEIGHT':
            best = 0
            stack = [(root, 1)] if root != -1 else []
            while stack:
                v, d = stack.pop()
                if d > best:
                    best = d
                if L[v] != -1:
                    stack.append((L[v], d + 1))
                if R[v] != -1:
                    stack.append((R[v], d + 1))
            out.append(str(best))
        else:
            res = []
            stack = [root] if root != -1 else []
            while stack:
                v = stack.pop()
                res.append(key[v])
                if R[v] != -1:
                    stack.append(R[v])
                if L[v] != -1:
                    stack.append(L[v])
            out.append(' '.join(map(str, res)) if res else 'EMPTY')
    print('\n'.join(out))

main()

