import sys
sys.setrecursionlimit(10000)

class Node:
    def __init__(self, k):
        self.k = k
        self.l = None
        self.r = None

def insert(n, x):
    if n is None:
        return Node(x), True
    if x < n.k:
        n.l, ok = insert(n.l, x)
        return n, ok
    if x > n.k:
        n.r, ok = insert(n.r, x)
        return n, ok
    return n, False

def search(n, x):
    if n is None:
        return False
    if x == n.k:
        return True
    return search(n.l if x < n.k else n.r, x)

def minnode(n):
    while n.l is not None:
        n = n.l
    return n

def delete(n, x):
    if n is None:
        return None, False
    if x < n.k:
        n.l, ok = delete(n.l, x)
        return n, ok
    if x > n.k:
        n.r, ok = delete(n.r, x)
        return n, ok
    if n.l is None:
        return n.r, True
    if n.r is None:
        return n.l, True
    s = minnode(n.r)
    n.k = s.k
    n.r, _ = delete(n.r, s.k)
    return n, True

def height(n):
    if n is None:
        return 0
    return 1 + max(height(n.l), height(n.r))

def pre(n, acc):
    if n is not None:
        acc.append(n.k)
        pre(n.l, acc)
        pre(n.r, acc)

lines = sys.stdin.read().split('\n')
q = int(lines[0])
root = None
out = []
for i in range(1, q + 1):
    parts = lines[i].split()
    op = parts[0]
    if op == 'INSERT':
        root, ok = insert(root, int(parts[1]))
        out.append('1' if ok else '0')
    elif op == 'SEARCH':
        out.append('1' if search(root, int(parts[1])) else '0')
    elif op == 'DELETE':
        root, ok = delete(root, int(parts[1]))
        out.append('1' if ok else '0')
    elif op == 'MIN':
        out.append('EMPTY' if root is None else str(minnode(root).k))
    elif op == 'MAX':
        if root is None:
            out.append('EMPTY')
        else:
            n = root
            while n.r is not None:
                n = n.r
            out.append(str(n.k))
    elif op == 'HEIGHT':
        out.append(str(height(root)))
    else:
        acc = []
        pre(root, acc)
        out.append(' '.join(map(str, acc)) if acc else 'EMPTY')
